        "jsCode": "// Generate comprehensive analytics and insights\nconst responseData = $input.all();\nconst currentData = $json;\n\n// Aggregate metrics from all responses\nlet analyticsReport = {\n  report_id: `analytics_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,\n  generated_at: new Date().toISOString(),\n  survey_id: currentData.survey_id,\n  participant_id: currentData.participant_id\n};\n\n// Key Performance Indicators\nanalyticsReport.kpis = {\n  response_completion_rate: currentData.call_quality.completion_rate,\n  average_sentiment_score: calculateSentimentScore(currentData.sentiment_analysis),\n  engagement_level: currentData.call_quality.engagement_level,\n  call_quality_score: calculateCallQualityScore(currentData.call_quality)\n};\n\n// Response analysis\nanalyticsReport.response_analysis = {\n  total_responses: currentData.survey_responses.length,\n  sentiment_breakdown: currentData.sentiment_analysis.sentiment_distribution,\n  average_rating: currentData.insights_summary.average_rating,\n  response_quality: assessResponseQuality(currentData.survey_responses)\n};\n\n// Insights and recommendations\nanalyticsReport.insights = {\n  key_themes: currentData.insights_summary.key_themes,\n  positive_highlights: currentData.insights_summary.positive_feedback.map(f => f.content).slice(0, 3),\n  improvement_areas: currentData.insights_summary.areas_for_improvement.map(f => f.content).slice(0, 3),\n  overall_assessment: currentData.insights_summary.overall_assessment\n};\n\n// Action items\nanalyticsReport.action_items = currentData.follow_up_actions.map(action => ({\n  action: action,\n  priority: determinePriority(action),\n  department: determineResponsibleDepartment(action),\n  timeline: determineTimeline(action)\n}));\n\n// Trend indicators (simplified for single response)\nanalyticsReport.trend_indicators = {\n  satisfaction_trend: 'stable',\n  engagement_trend: currentData.call_quality.engagement_level === 'high' ? 'positive' : 'neutral',\n  response_quality_trend: 'improving'\n};\n\nfunction calculateSentimentScore(sentimentAnalysis) {\n  const weights = {\n    'very_positive': 10,\n    'positive': 7,\n    'neutral': 5,\n    'negative': 3,\n    'very_negative': 1\n  };\n  \n  const distribution = sentimentAnalysis.sentiment_distribution;\n  let totalScore = 0;\n  let totalResponses = 0;\n  \n  for (const [sentiment, count] of Object.entries(distribution)) {\n    totalScore += weights[sentiment] * count;\n    totalResponses += count;\n  }\n  \n  return totalResponses > 0 ? totalScore / totalResponses : 5;\n}\n\nfunction calculateCallQualityScore(callQuality) {\n  let score = 5; // Base score\n  \n  // Completion rate impact\n  if (callQuality.completion_rate > 80) score += 2;\n  else if (callQuality.completion_rate > 60) score += 1;\n  else if (callQuality.completion_rate < 40) score -= 2;\n  \n  // Engagement impact\n  if (callQuality.engagement_level === 'high') score += 1.5;\n  else if (callQuality.engagement_level === 'low') score -= 1.5;\n  \n  // Response count impact\n  if (callQuality.response_count > 5) score += 1;\n  else if (callQuality.response_count < 2) score -= 1;\n  \n  return Math.max(1, Math.min(10, score));\n}\n\nfunction assessResponseQuality(responses) {\n  const qualityFactors = {\n    average_length: responses.reduce((sum, r) => sum + r.response_text.length, 0) / responses.length,\n    detailed_responses: responses.filter(r => r.response_text.length > 50).length,\n    engagement_indicators: responses.filter(r => r.response_text.includes('because') || r.response_text.includes('specifically')).length\n  };\n  \n  if (qualityFactors.average_length > 100 && qualityFactors.detailed_responses > 2) {\n    return 'high';\n  } else if (qualityFactors.average_length > 50) {\n    return 'medium';\n  } else {\n    return 'low';\n  }\n}\n\nfunction determinePriority(action) {\n  const priorities = {\n    'immediate_escalation': 'urgent',\n    'customer_retention_outreach': 'high',\n    'survey_redesign_consideration': 'medium'\n  };\n  return priorities[action] || 'low';\n}\n\nfunction determineResponsibleDepartment(action) {\n  const departments = {\n    'immediate_escalation': 'customer_success',\n    'customer_retention_outreach': 'sales',\n    'survey_redesign_consideration': 'product_team'\n  };\n  return departments[action] || 'customer_success';\n}\n\nfunction determineTimeline(action) {\n  const timelines = {\n    'immediate_escalation': '4 hours',\n    'customer_retention_outreach': '24 hours',\n    'survey_redesign_consideration': '1 week'\n  };\n  return timelines[action] || '48 hours';\n}\n\nreturn { analytics_report: analyticsReport };"
