sponses) {\n  const reasons = [];\n  if (completion < 60) reasons.push('Insufficient completion rate');\n  if (quality < 5) reasons.push('Low response quality');\n  if (responses < 2) reasons.push('Insufficient number of responses');\n  return reasons.join(', ');\n}\n\nreturn { incentive_processing: incentiveProcessing };"
